            return false;
    }
#ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
}
if(decoder->protected_->state == FLAC__STREAM_DECODER_READ_FRAME && frame_crc == x) {
#endif
    if(do_full_decode) {
        /* Undo any special channel coding */
        undo_channel_coding(decoder);
        ...
    }
